    public void set_file_value(Control owner,Resource data,Resource definition,Resource property,Resource? root,Variant value)
    {
        if(!_properties.accepts(property,value))return;var key=property.Get("id").AsStringName();var previous=_data.copy_value(_data.object_get_value(data,key,default));if(same_value(previous,value))return;root??=data;var target=data.ResourcePath.Length>0&&!data.ResourcePath.Contains("::",StringComparison.Ordinal)?data:root;var model=Ui<RefCounted>(owner,"model");var history=model.Get("history").As<UndoRedo>();var action=new InspectorFilePropertyAction(model,data,root,target,key,previous,_data.copy_value(value));history.CreateAction("Change "+property.Get("label").AsString());history.AddDoMethod(new Callable(action,nameof(InspectorFilePropertyAction.restore_after)));history.AddUndoMethod(new Callable(action,nameof(InspectorFilePropertyAction.restore_before)));history.AddDoReference(action);history.CommitAction();owner.Call("_run_inspector_updaters");
    }
    public void add_file_object_value(Control owner,Resource data,Resource definition,Resource property,VBoxContainer parent,Resource? root)
    {
        if(owner.Call("_add_special_file_value",data,definition,property,parent,root!=null?Variant.From(root):default).AsBool())return;var key=property.Get("id").AsStringName();var options=property.Get("options").AsGodotDictionary();Variant Current()=>_definitions.value_for(data,property);var current=Current();var heading=new HBoxContainer();parent.AddChild(heading);heading.AddChild(new Label{Text=property.Get("label").AsString(),SizeFlagsHorizontal=Control.SizeFlags.ExpandFill,TextOverrunBehavior=TextServer.OverrunBehavior.TrimEllipsis,TooltipText=property.Get("label").AsString()});var reset=new Button{Name=key+"_reset",Text="↺",Visible=!same_value(current,_properties.create_default(property))};heading.AddChild(reset);void Set(Variant value){set_file_value(owner,data,definition,property,root,value);reset.Visible=!same_value(Current(),_properties.create_default(property));}reset.Pressed+=()=>Set(_properties.create_default(property));if(options.ContainsKey("choices")){var choice=choice_editor(parent,property,current.AsInt32());choice.ItemSelected+=index=>Set(index);return;}var model=Ui<RefCounted>(owner,"model");void Preview(Variant value){_data.set_value(data,key,value);model.EmitSignal("changed");}var updaters=owner.Get("_updaters").AsGodotArray();void Wire(SpinBox input,Func<double,Variant> make){Variant origin=current;input.Connect("interaction_started",Callable.From(()=>origin=_data.copy_value(Current())));input.Connect("preview_changed",Callable.From<double>(n=>Preview(make(n))));input.Connect("drag_committed",Callable.From<double>(n=>{var next=make(n);_data.set_value(data,key,origin);Set(next);}));input.Connect("drag_cancelled",Callable.From(()=>Preview(origin)));input.ValueChanged+=n=>Set(make(n));}
        switch((Variant.Type)property.Get("value_type").AsInt32()){
        case Variant.Type.Int:case Variant.Type.Float:var numberInput=number_editor(owner,parent,current.AsDouble(),property);Wire(numberInput,n=>property.Get("value_type").AsInt32()==(int)Variant.Type.Int?Variant.From((long)n):Variant.From(n));updaters.Add(Callable.From(()=>{if(!numberInput.Get("dragging").AsBool())set_number_silent(numberInput,Current().AsDouble());}));break;
        case Variant.Type.Vector2:case Variant.Type.Vector3:int count=property.Get("value_type").AsInt32()==(int)Variant.Type.Vector2?2:3;for(int i=0;i<count;i++){int axis=i;var row=new HBoxContainer();parent.AddChild(row);row.AddChild(new Label{Text=new[]{"X","Y","Z"}[axis],Modulate=new Color(new[]{"ee9e9e","9ed8b5","99bce8"}[axis])});var input=number(owner,ActorAnimationOperations.Component(current,axis).AsDouble(),options.GetValueOrDefault("step",.01).AsDouble());input.Name=key+"_"+axis;row.AddChild(input);Wire(input,n=>ActorAnimationOperations.WithComponent(Current(),axis,n));updaters.Add(Callable.From(()=>{if(!input.Get("dragging").AsBool())input.SetValueNoSignal(ActorAnimationOperations.Component(Current(),axis).AsDouble());}));}break;
        case Variant.Type.String:case Variant.Type.StringName:if(options.GetValueOrDefault("file_picker",false).AsBool()){owner.Call("_add_saved_object_file_slot",data,definition,property,parent,root!=null?Variant.From(root):default);break;}var text=new LineEdit{Name=key+"_text",Text=current.ToString(),SizeFlagsHorizontal=Control.SizeFlags.ExpandFill,Editable=!options.GetValueOrDefault("read_only",false).AsBool()};parent.AddChild(text);void Submit()=>Set(property.Get("value_type").AsInt32()==(int)Variant.Type.StringName?Variant.From(new StringName(text.Text)):Variant.From(text.Text));text.TextSubmitted+=_=>Submit();text.FocusExited+=Submit;updaters.Add(Callable.From(()=>{if(!text.HasFocus())text.Text=Current().ToString();}));break;
        case Variant.Type.Bool:var toggle=new CheckButton{Name=key.ToString(),ButtonPressed=current.AsBool()};parent.AddChild(toggle);toggle.Toggled+=n=>Set(n);updaters.Add(Callable.From(()=>toggle.SetPressedNoSignal(Current().AsBool())));break;
        case Variant.Type.Color:var color=new LiveColorPickerButton();color.Name=key.ToString();color.Color=current.AsColor();parent.AddChild(color);color.Connect("preview_changed",Callable.From<Color>(n=>Preview(n)));color.Connect("drag_committed",Callable.From<Color,Color>((original,n)=>{_data.set_value(data,key,original);Set(n);}));color.Connect("drag_cancelled",Callable.From<Color>(original=>Preview(original)));updaters.Add(Callable.From(()=>color.Call("set_color_silent",Current())));break;}
    }
